const input = $('Webhook').first().json;
const clause = input.body || input;

if (!clause.clause_text) {
  throw new Error('clause_text is required');
}

return [{
  json: {
    clause_instance_id: clause.clause_instance_id || 'unknown',
    clause_id: clause.clause_id || 'unknown',
    clause_text: clause.clause_text,
    run_id: clause.run_id || '',
    document_id: clause.document_id || '',
    blueprint_version_id: clause.blueprint_version_id || null,
    matter_policy_id: clause.matter_policy_id || null,
    contract_type: clause.contract_type || 'nueva_planta',
    started_at: new Date().toISOString()
  }
}];

// CG-008.P: Hybrid Router Stage 1 with Stability Patches
// Combines Keyword Router + LLM fallback decision

const clauseText = $json.clause_text || '';
const heading = $json.heading || '';

// ============================================================
// CG-008.P: KEYWORD PATTERNS WITH STABILITY PATCHES
// ============================================================

const KEYWORD_PATTERNS = {
    // HIGH PRIORITY - INDEMNITY
    IndemnityProdCo: {
        patterns: [
            /ProdCo\s+(shall|will|agrees?\s+to)\s+indemnify/i,
            /indemnify,?\s+defend,?\s+(and\s+)?hold\s+harmless\s+Amazon/i,
            /Amazon\s+Indemnitees/i,
            /from\s+and\s+against\s+any\s+(and\s+all\s+)?claims/i,
            /ProdCo\s+shall\s+defend/i,
            /hold\s+Amazon\s+harmless/i
        ],
        negative: [/Amazon\s+(shall|will)\s+indemnify/i],
        min_matches: 1,
        confidence: 0.90,
        priority: 1
    },
    IndemnityAmazon: {
        patterns: [
            /Amazon\s+(shall|will|agrees?\s+to)\s+indemnify/i,
            /indemnify\s+ProdCo/i,
            /ProdCo\s+Indemnitees/i,
            /hold\s+ProdCo\s+harmless/i
        ],
        negative: [/ProdCo\s+(shall|will)\s+indemnify/i],
        min_matches: 1,
        confidence: 0.90,
        priority: 1
    },

    // CG-008.P Fix A: LiabilityLimitation with STRONG patterns
    LiabilityLimitation: {
        patterns: [
            // Strong ALL CAPS patterns
            /IN\s+NO\s+EVENT\s+SHALL/i,
            /CONSEQUENTIAL\s+DAMAGES/i,
            /INDIRECT\s+DAMAGES/i,
            /INCIDENTAL\s+DAMAGES/i,
            /PUNITIVE\s+DAMAGES/i,
            /AGGREGATE\s+LIABILITY/i,
            /SHALL\s+NOT\s+EXCEED/i,
            /LIMITATION\s+OF\s+LIABILITY/i,
            /MAXIMUM\s+LIABILITY/i,
            /LOST\s+PROFITS/i,
            /UNDER\s+NO\s+CIRCUMSTANCES/i,
            // Mixed case
            /aggregate\s+liability\s+shall\s+not\s+exceed/i,
            /liability\s+shall\s+be\s+limited\s+to/i,
            /liability\s+cap/i
        ],
        negative: [
            /shall\s+indemnify/i,
            /gross\s+negligence/i,
            /willful\s+misconduct/i
        ],
        min_matches: 1,
        confidence: 0.92,
        priority: 1
    },

    // CG-008.P Fix B: RightsReversion with termination context negatives
    RightsReversion: {
        patterns: [
            /reversion\s+of\s+rights/i,
            /rights\s+shall\s+revert/i,
            /turnaround/i,
            /reacquisition/i,
            /revert\s+to\s+ProdCo/i,
            /no\s+reversion/i,
            /waives?\s+(any\s+)?reversion/i
        ],
        negative: [
            // CG-008.P: Termination context → TerminationConsequences wins
            /upon\s+termination/i,
            /effect\s+of\s+termination/i,
            /following\s+termination/i,
            /termination\s+fee/i,
            /kill\s+fee/i,
            /return\s+(all\s+)?materials/i,
            /deliver\s+(all\s+)?work\s+product/i
        ],
        min_matches: 1,
        confidence: 0.92,
        priority: 1
    },

    // CG-008: DataProtection with HIGH PRIORITY
    DataProtection: {
        patterns: [
            /\bGDPR\b/i,
            /\bCCPA\b/i,
            /data\s+protection\s+laws?/i,
            /data\s+controller/i,
            /data\s+processor/i,
            /personal\s+data/i,
            /processing\s+of\s+personal\s+data/i,
            /data\s+subject\s+rights/i,
            /privacy\s+impact\s+assessment/i
        ],
        negative: [
            /trade\s+secrets?/i,
            /proprietary\s+information/i
        ],
        min_matches: 1,
        confidence: 0.90,
        priority: 1
    },

    // CG-008: Confidentiality WITHOUT GDPR patterns
    Confidentiality: {
        patterns: [
            /maintain\s+in\s+strict\s+confidence/i,
            /confidential\s+information/i,
            /non-public\s+information/i,
            /\bNPI\b/,
            /shall\s+not\s+disclose/i,
            /keep\s+confidential/i,
            /proprietary\s+information/i,
            /trade\s+secrets/i,
            /confidentiality\s+obligations/i,
            /non-disclosure/i
        ],
        negative: [
            /\bGDPR\b/i,
            /data\s+protection/i,
            /data\s+controller/i,
            /personal\s+data/i,
            /assign/i
        ],
        min_matches: 1,
        confidence: 0.90,
        priority: 2
    },

    // CG-008: Assignment with expanded negatives
    Assignment: {
        patterns: [
            /may\s+not\s+assign/i,
            /shall\s+not\s+assign/i,
            /assignment\s+is\s+void/i,
            /successors\s+and\s+assigns/i,
            /change\s+of\s+control/i,
            /assignment\s+of\s+this\s+Agreement/i,
            /may\s+freely\s+assign/i,
            /Amazon\s+may\s+assign/i
        ],
        negative: [
            /counterparts/i,
            /entire\s+agreement/i,
            /confidential/i,
            /disclose/i,
            /non-disclosure/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },

    // TerminationConsequences with RightsReversion negatives
    TerminationConsequences: {
        patterns: [
            /upon\s+termination/i,
            /effect\s+of\s+termination/i,
            /following\s+termination/i,
            /termination\s+payment/i,
            /kill\s+fee/i,
            /termination\s+fee/i,
            /return\s+all\s+materials/i
        ],
        negative: [],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },

    // TerminationRights
    TerminationRights: {
        patterns: [
            /may\s+terminate\s+this\s+Agreement/i,
            /right\s+to\s+terminate/i,
            /terminate\s+immediately/i,
            /upon\s+\\d+\s+days.*notice/i,
            /material\s+breach/i,
            /terminate\s+for\s+cause/i,
            /terminate\s+for\s+convenience/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },

    // AuditRights with negatives
    AuditRights: {
        patterns: [
            /audit\s+rights/i,
            /right\s+to\s+audit/i,
            /inspect.*books\s+and\s+records/i,
            /books\s+and\s+records/i,
            /accountant/i,
            /examine.*accounting\s+records/i
        ],
        negative: [
            /grant/i,
            /license/i,
            /exploitation/i,
            /in\s+perpetuity/i
        ],
        min_matches: 1,
        confidence: 0.90,
        priority: 2
    },

    // ServicesScope expanded
    ServicesScope: {
        patterns: [
            /ProdCo\s+(shall|will)\s+provide\s+(the\s+)?services/i,
            /production\s+services/i,
            /scope\s+of\s+services/i,
            /services\s+to\s+be\s+provided/i,
            /deliverables/i,
            /services\s+as\s+set\s+forth\s+in\s+Exhibit/i,
            /production\s+of\s+the\s+(Series|Program|Film)/i,
            /set\s+forth\s+in\s+Exhibit\s+A/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },

    // Other families
    ForceMajeure: {
        patterns: [
            /force\s+majeure/i,
            /acts?\s+of\s+God/i,
            /war,?\s+terrorism/i,
            /beyond\s+reasonable\s+control/i,
            /natural\s+disaster/i,
            /pandemic/i,
            /earthquake|flood|hurricane/i
        ],
        min_matches: 1,
        confidence: 0.92,
        priority: 1
    },
    RightsGrant: {
        patterns: [
            /grants?\s+to\s+Amazon/i,
            /all\s+rights.*throughout\s+the\s+universe/i,
            /in\s+perpetuity/i,
            /exclusive\s+license/i,
            /exploitation\s+rights/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },
    Insurance: {
        patterns: [
            /obtain\s+and\s+maintain.*insurance/i,
            /errors\s+and\s+omissions/i,
            /\bE\s*&\s*O\b/i,
            /commercial\s+general\s+liability/i,
            /certificate\s+of\s+insurance/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },
    DisputeResolution: {
        patterns: [
            /binding\s+arbitration/i,
            /dispute.*resolution/i,
            /mediation/i,
            /exclusive\s+jurisdiction/i,
            /governed\s+by\s+the\s+laws/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },
    AmazonControl: {
        patterns: [
            /sole\s+and\s+final\s+control/i,
            /Amazon['']?s\s+sole\s+discretion/i,
            /subject\s+to\s+Amazon['']?s\s+approval/i,
            /final\s+cut/i,
            /creative\s+control/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },
    Publicity: {
        patterns: [
            /publicity\s+materials/i,
            /press\s+release/i,
            /use\s+of\s+name\s+and\s+likeness/i,
            /promotional\s+purposes/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },
    PaymentCredits: {
        patterns: [
            /Amazon\s+(shall|will)\s+pay/i,
            /payable\s+within\s+\\d+\s+days/i,
            /net\s+30/i,
            /production\s+fee/i,
            /milestone\s+payment/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },
    GoverningLaw: {
        patterns: [
            /governed\s+by.*laws\s+of/i,
            /laws\s+of\s+(the\s+State\s+of\s+)?California/i,
            /exclusive\s+jurisdiction/i,
            /venue.*shall\s+be/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    },
    GeneralProvisions: {
        patterns: [
            /entire\s+agreement/i,
            /supersedes\s+all\s+prior/i,
            /severability/i,
            /executed\s+in\s+counterparts/i,
            /no\s+waiver/i
        ],
        min_matches: 1,
        confidence: 0.85,
        priority: 3
    },
    RepsProdCo: {
        patterns: [
            /ProdCo\s+represents\s+and\s+warrants/i,
            /ProdCo\s+warrants\s+that/i,
            /full\s+authority\s+to\s+enter/i
        ],
        min_matches: 1,
        confidence: 0.88,
        priority: 2
    }
};

// Routing function
function routeClause(text) {
    const results = [];
    const lowerText = text.toLowerCase();

    for (const [family, config] of Object.entries(KEYWORD_PATTERNS)) {
        let matchCount = 0;
        let matchedPatterns = [];

        // Check positive patterns
        for (const pattern of config.patterns) {
            if (pattern.test(text)) {
                matchCount++;
                matchedPatterns.push(pattern.source);
            }
        }

        // Check negative patterns
        let hasNegative = false;
        if (config.negative && config.negative.length > 0) {
            for (const negPattern of config.negative) {
                if (negPattern.test(text)) {
                    hasNegative = true;
                    break;
                }
            }
        }

        if (matchCount >= (config.min_matches || 1) && !hasNegative) {
            results.push({
                family,
                matchCount,
                matchedPatterns,
                confidence: config.confidence,
                priority: config.priority
            });
        }
    }

    // Sort by priority (lower = higher priority), then by match count
    results.sort((a, b) => {
        if (a.priority !== b.priority) return a.priority - b.priority;
        return b.matchCount - a.matchCount;
    });

    return results;
}

// Execute routing
const routingResults = routeClause(clauseText);
const topMatch = routingResults[0];

const detected_family = topMatch ? topMatch.family : 'OtherUnknown';
const confidence = topMatch ? topMatch.confidence : 0.0;
const needs_llm = !topMatch || topMatch.confidence < 0.7;

return [{
    json: {
        ...$json,
        detected_family,
        _routing_method: needs_llm ? 'PENDING_LLM' : 'KEYWORD',
        _keyword_confidence: confidence,
    routing_confidence: confidence,
        _matches: routingResults.slice(0, 3),
        needs_llm_fallback: needs_llm
    }
}];

// Get data from either Parse LLM Result (LLM path) or Hybrid Router (direct path)
let prevData;
try {
  prevData = $('Parse LLM Result').first().json;
} catch (e) {
  // Direct path - get from Hybrid Router
  prevData = $('Hybrid Router (Stage 1)').first().json;
}

let embedding = null;
try {
  embedding = $json.data?.[0]?.embedding || null;
} catch (e) {
  console.log('Embedding parse error:', e.message);
}

return [{ json: { ...prevData, clauseEmbedding: embedding } }];

const prevData = $('Parse Embedding').first().json;
let ragResults = [];

try {
  // Handle both array response and empty response
  const response = $input.first().json;
  if (Array.isArray(response)) {
    ragResults = response;
  } else if (response && typeof response === 'object') {
    // If it's an object with error, treat as empty
    ragResults = [];
  }
} catch (e) {
  console.log('RAG parse error:', e.message);
  ragResults = [];
}

// Group examples by acceptance level
const acceptableExamples = ragResults.filter(r => r.acceptance === 'ACCEPTABLE').slice(0, 2);
const passableExamples = ragResults.filter(r => r.acceptance === 'PASSABLE').slice(0, 2);
const unacceptableExamples = ragResults.filter(r => r.acceptance === 'UNACCEPTABLE').slice(0, 2);

// Format for prompt
const formatExample = (ex) => `[${ex.acceptance}] (similarity: ${(ex.similarity * 100).toFixed(0)}%)\n${ex.example_text.substring(0, 500)}...`;

const ragContext = {
  hasResults: ragResults.length > 0,
  totalFound: ragResults.length,
  acceptableExamples: acceptableExamples.map(formatExample),
  passableExamples: passableExamples.map(formatExample),
  unacceptableExamples: unacceptableExamples.map(formatExample),
  topSimilarity: ragResults[0]?.similarity || 0,
  topAcceptance: ragResults[0]?.acceptance || 'NONE'
};

return [{ json: { ...prevData, ragContext, ragResults } }];

// Enrich Policy (CG-012) - with v2→v3 adapter
// =============================================
// This node enriches the policy spec with playbook data and normalizes
// the acceptability_matrix to v3 format for consistent consumption.

// Get data from Parse RAG Results and Playbook Spec
const prevData = $('Parse RAG Results').first().json;
const family = prevData.detected_family || 'OtherUnknown';

// Get playbook spec from database response (from Get Playbook Spec node)
let playbookSpec = null;
try {
    const specResponse = $input.all()[0]?.json;
    if (Array.isArray(specResponse) && specResponse.length > 0) {
        playbookSpec = specResponse[0];
    } else if (specResponse && !Array.isArray(specResponse)) {
        playbookSpec = specResponse;
    }
} catch (e) {
    console.log('Playbook spec parse error:', e.message);
}

// -------------------------
// v2→v3 Adapter
// -------------------------
function normalizeAcceptabilityMatrix(matrix) {
    const empty = {
        acceptable: { description: '', examples: [] },
        passable: { description: '', requires_approval: '', variations: [] },
        unacceptable: { description: '', action: '', patterns: [] }
    };
    if (!matrix || typeof matrix !== 'object') return empty;

    // v3 already OK - check if patterns[0] is an object
    const hasV3 = matrix?.unacceptable?.patterns?.length &&
        typeof matrix.unacceptable.patterns[0] === 'object';
    if (hasV3) return matrix;

    // v2: arrays of strings (legacy)
    const unacceptableStrings = matrix?.unacceptable?.patterns || matrix?.unacceptable || matrix?.unacceptable_patterns || [];
    const passableStrings = matrix?.passable?.variations || matrix?.passable || matrix?.passable_variations || [];
    const acceptableStrings = matrix?.acceptable?.examples || matrix?.acceptable || matrix?.acceptable_examples || [];

    return {
        acceptable: {
            description: matrix?.acceptable?.description || '',
            examples: (Array.isArray(acceptableStrings) ? acceptableStrings : []).map((s, i) => ({
                id: `acc-legacy-${i + 1}`,
                pattern: String(s),
                example: '',
                reason: 'requires playbook_specs data',
                risk_level: 'NONE'
            }))
        },
        passable: {
            description: matrix?.passable?.description || '',
            requires_approval: matrix?.passable?.requires_approval || '',
            variations: (Array.isArray(passableStrings) ? passableStrings : []).map((s, i) => ({
                id: `pas-legacy-${i + 1}`,
                pattern: String(s),
                condition: '',
                example: '',
                reason: 'requires playbook_specs data',
                risk_level: 'MEDIUM'
            }))
        },
        unacceptable: {
            description: matrix?.unacceptable?.description || '',
            action: matrix?.unacceptable?.action || 'REJECT',
            patterns: (Array.isArray(unacceptableStrings) ? unacceptableStrings : []).map((s, i) => ({
                id: `unacc-legacy-${i + 1}`,
                pattern: String(s),
                example: '',
                reason: 'requires playbook_specs data',
                risk_level: 'CRITICAL'
            }))
        }
    };
}

// Build policySpec from database data or fallback
let policySpec;
if (playbookSpec && playbookSpec.family_id) {
    // Normalize the matrix to v3
    const matrixV3 = normalizeAcceptabilityMatrix(playbookSpec.acceptability_matrix);

    policySpec = {
        clause_family: playbookSpec.family_id,
        display_name: playbookSpec.display_name,
        priority: playbookSpec.priority,
        requires_legal_review: playbookSpec.requires_legal_review,
        rule_id: `PB:v2026-02:${playbookSpec.family_id}-Core`,
        has_policy_spec: true,

        // Amazon position data
        amazon_position: playbookSpec.amazon_position,
        standard_position: {
            text: playbookSpec.amazon_position?.summary || '',
            summary: playbookSpec.amazon_position?.summary || '',
            core_requirements: playbookSpec.amazon_position?.core_requirements || []
        },

        // Acceptability data (v3 normalized)
        acceptability_matrix: matrixV3,

        // v3 objects for advanced consumers (Paranoid, Valuator)
        unacceptable_patterns: matrixV3.unacceptable.patterns,
        passable_variations: matrixV3.passable.variations,
        acceptable_examples: matrixV3.acceptable.examples,

        // Flat labels for compatibility/logging/UI
        unacceptable_pattern_labels: matrixV3.unacceptable.patterns.map(p => p.pattern),
        passable_variation_labels: matrixV3.passable.variations.map(v => v.pattern),
        acceptable_example_labels: matrixV3.acceptable.examples.map(e => e.pattern),

        // Negotiation and risk
        negotiation_guidance: playbookSpec.negotiation_guidance,
        risk_assessment: playbookSpec.risk_assessment,
        detection_patterns: playbookSpec.detection_patterns,

        // Policies
        analysis_mode: 'MODE_ENUMERATED_DEVIATIONS',
        required: true,
        routing_policy: {
            type: playbookSpec.priority === 'CRITICAL' ? 'ESCALATE_IF_UNACCEPTABLE' : 'LOG_ONLY',
            block_export: playbookSpec.priority === 'CRITICAL'
        },
        decision_policy: {
            anchor_conf_threshold: 0.85,
            gating_logic: 'STANDARD',
            block_export_if_escalated: playbookSpec.priority === 'CRITICAL'
        }
    };
} else {
    // Fallback for families without playbook spec
    policySpec = {
        id: null,
        rule_id: `default:${family}`,
        clause_family: family,
        required: true,
        analysis_mode: 'MODE_ENUMERATED_DEVIATIONS',
        standard_position: { text: 'Not defined', summary: 'Manual review required' },
        acceptability_matrix: normalizeAcceptabilityMatrix(null),
        unacceptable_patterns: [],
        passable_variations: [],
        acceptable_examples: [],
        unacceptable_pattern_labels: [],
        passable_variation_labels: [],
        acceptable_example_labels: [],
        routing_policy: { type: 'ESCALATE', block_export: true },
        decision_policy: { anchor_conf_threshold: 0.85, gating_logic: 'STANDARD', block_export_if_escalated: true },
        has_policy_spec: false
    };
}

const TH_ANCHOR = policySpec.decision_policy?.anchor_conf_threshold || 0.85;
const TH_CONF = 0.80;

return [{ json: { ...prevData, policySpec, playbookSpec, TH_ANCHOR, TH_CONF } }];

// Build Family Prompt (CG-012) - v3.0 rendering + English prompts + RAG injection
// ================================================================================
// This node builds the system/user prompts for Paranoid and Valuator agents,
// correctly rendering v3.0 acceptability_matrix objects and injecting RAG context.

const data = $('Enrich Policy').first().json;
const family = data.policySpec?.clause_family || 'OtherUnknown';
const clauseText = data.clause_text;
const policySpec = data.policySpec || {};
const playbookSpec = data.playbookSpec;
const ragContext = data.ragContext || {};

// -------------------------
// v3 Formatters
// -------------------------
function formatUnacceptable(patterns = []) {
    if (!Array.isArray(patterns) || !patterns.length) return '  • None defined';
    return patterns.map(p => {
        if (!p || typeof p !== 'object') return `  • ${String(p)}`;
        return [
            `  • [${p.id || 'unacc'}] ${p.pattern || ''}`,
            p.example ? `    Example: "${p.example}"` : null,
            p.reason ? `    Reason: ${p.reason}` : null,
            p.risk_level ? `    Risk: ${p.risk_level}` : null,
        ].filter(Boolean).join('\n');
    }).join('\n');
}

function formatPassable(vars = []) {
    if (!Array.isArray(vars) || !vars.length) return '  • None defined';
    return vars.map(v => {
        if (!v || typeof v !== 'object') return `  • ${String(v)}`;
        return [
            `  • [${v.id || 'pas'}] ${v.pattern || v.variation || ''}`,
            v.condition ? `    Condition: ${v.condition}` : null,
            v.example ? `    Example: "${v.example}"` : null,
            v.reason ? `    Reason: ${v.reason}` : null,
            v.risk_level ? `    Risk: ${v.risk_level}` : null,
        ].filter(Boolean).join('\n');
    }).join('\n');
}

function formatAcceptable(examples = []) {
    if (!Array.isArray(examples) || !examples.length) return '  • None defined';
    return examples.slice(0, 3).map(e => {
        if (!e || typeof e !== 'object') return `  • ${String(e)}`;
        return [
            `  • [${e.id || 'acc'}] ${e.pattern || ''}`,
            e.example ? `    Example: "${e.example}"` : null,
            e.reason ? `    Reason: ${e.reason}` : null,
        ].filter(Boolean).join('\n');
    }).join('\n');
}

function formatRedFlags(flags = []) {
    if (!Array.isArray(flags) || !flags.length) return '  • None defined';
    return flags.map(f => `  • "${f}" → Severity: high, Category: MatchesUnacceptable`).join('\n');
}

function formatMustHave(anchors = []) {
    if (!Array.isArray(anchors) || !anchors.length) return '  • None defined';
    return anchors.map(a => `  • "${a}"`).join('\n');
}

function formatCoreRequirements(reqs = []) {
    if (!Array.isArray(reqs) || !reqs.length) return '  • None defined';
    return reqs.map(r => `  • ${r}`).join('\n');
}

function formatEscalationTriggers(triggers = []) {
    if (!Array.isArray(triggers) || !triggers.length) return '  • None defined';
    return triggers.map(t => `  • ${t}`).join('\n');
}

// -------------------------
// RAG Context Formatter
// -------------------------
function formatRagExamples(rag = {}) {
    const topUnacc = (rag.unacceptableExamples || rag.unacceptable || []).slice(0, 2);
    const topAcc = (rag.acceptableExamples || rag.acceptable || []).slice(0, 1);
    const topPass = (rag.passableExamples || rag.passable || []).slice(0, 1);

    let out = '';
    if (topUnacc.length) {
        out += '\n  UNACCEPTABLE examples (for grounding):\n';
        out += topUnacc.map((e, i) => `    ${i + 1}. ${String(e.example_text || e.text || e).slice(0, 400)}...`).join('\n');
    }
    if (topAcc.length) {
        out += '\n  ACCEPTABLE examples (for grounding):\n';
        out += topAcc.map((e, i) => `    ${i + 1}. ${String(e.example_text || e.text || e).slice(0, 400)}...`).join('\n');
    }
    if (topPass.length) {
        out += '\n  PASSABLE examples (for grounding):\n';
        out += topPass.map((e, i) => `    ${i + 1}. ${String(e.example_text || e.text || e).slice(0, 400)}...`).join('\n');
    }

    return out || '  • No RAG examples available';
}

// -------------------------
// Build Prompts
// -------------------------
let paranoidSystem, valuatorSystem, TH_ANCHOR;

if (playbookSpec && playbookSpec.amazon_position) {
    const pos = playbookSpec.amazon_position || {};
    const matrix = playbookSpec.acceptability_matrix || {};
    const detection = playbookSpec.detection_patterns || {};
    const risk = playbookSpec.risk_assessment || {};

    // PARANOID SYSTEM PROMPT (English, imperative, v2.0)
    paranoidSystem = `PARANOID ANALYSIS AGENT — ${playbookSpec.display_name}
Version: 2.0 | Family: ${playbookSpec.family_id} | Priority: ${playbookSpec.priority}

YOUR MISSION
You must identify EVERY deviation, risk, or concern with HIGH RECALL.
False positives are acceptable. False negatives are NOT acceptable.

CRITICAL RULE (NO EMPTY OBSERVATIONS)
If ANY red_flag is found OR ANY unacceptable pattern is matched OR ANY must-have is missing:
- observations.length MUST be > 0
- risk_level MUST be RED or YELLOW (never GREEN)

MATCHING RULES (DETERMINISTIC)
- Match is case-insensitive and whitespace-tolerant.
- evidence MUST be an exact substring from clause_text.
- offsets are 0-indexed character positions in clause_text.
- If a must-have is missing: evidence = "[missing: <anchor>]" and offsets = {start:0,end:0}

AMAZON STANDARD POSITION
${pos.summary || 'Not defined'}

CORE REQUIREMENTS
${formatCoreRequirements(pos.core_requirements)}

MUST-HAVE ANCHORS (required elements)
${formatMustHave(detection.must_have)}

RED FLAGS (report immediately if found)
${formatRedFlags(detection.red_flags)}

UNACCEPTABLE PATTERNS (must reject if matched)
${formatUnacceptable(matrix?.unacceptable?.patterns)}

PASSABLE VARIATIONS (acceptable only with legal approval)
${formatPassable(matrix?.passable?.variations)}

ACCEPTABLE EXAMPLES (fully compliant language)
${formatAcceptable(matrix?.acceptable?.examples)}

ESCALATION TRIGGERS
${formatEscalationTriggers(risk.escalation_triggers)}

OUTPUT FORMAT (JSON ONLY)
Return exactly this structure:
{
  "observations": [
    {
      "evidence": "exact substring from clause_text OR [missing: <anchor>]",
      "offsets": { "start": 0, "end": 0 },
      "change_type": "missing|added|modified",
      "possible_category": "MatchesUnacceptable|MissingRequired|PassableVariation|UnknownChange",
      "pattern_matched": "red_flag OR pattern name",
      "confidence": 0.0,
      "severity": "high|medium|low",
      "reason": "brief explanation",
      "playbook_reference": "pattern id or null"
    }
  ],
  "summary": {
    "counts": {"total": 0, "missing": 0, "added": 0, "modified": 0},
    "coverage_confidence": 0.0,
    "red_flags_found": 0,
    "unacceptable_patterns_found": 0,
    "must_have_missing": 0
  },
  "risk_level": "RED|YELLOW|GREEN"
}`;

    // VALUATOR SYSTEM PROMPT (English, deterministic)
    valuatorSystem = `VALUATOR AGENT — ${playbookSpec.display_name}
Version: 2.0 | Mode: MODE_ENUMERATED_DEVIATIONS | Priority: ${playbookSpec.priority}

YOUR MISSION
Based on Paranoid observations, determine final_status and propose changes.

RULES
1. NO NEW TEXT - proposed replacement_text MUST come from playbook standard_position or fallback_clauses
2. SOURCE REQUIRED - every proposed_change needs source_reference with exact_text
3. DETERMINISTIC MAPPING:
   - observations contains MatchesUnacceptable → final_status = UnacceptableDeviation
   - observations contains MissingRequired → final_status = UnacceptableDeviation  
   - observations only PassableVariation → final_status = AcceptableDeviation
   - observations empty AND risk_level=GREEN → final_status = Compliant
4. ESCALATE ON UNCERTAINTY - if confidence_overall < 0.75 → escalation_recommended = true

STANDARD POSITION (use as source for replacement_text):
${pos.summary || 'Not defined'}

OUTPUT FORMAT (JSON ONLY):
{
  "final_status": "Compliant|AcceptableDeviation|UnacceptableDeviation|Ambiguous",
  "escalation_recommended": false,
  "escalation_reason": null,
  "proposed_changes": [
    {
      "target_text": "exact text from clause to replace",
      "replacement_text": "text from playbook standard_position",
      "change_type": "delete|replace|insert",
      "priority": "critical|high|medium",
      "source_reference": {
        "type": "standard_position|fallback_clause",
        "exact_text": "verbatim from playbook"
      }
    }
  ],
  "confidence_overall": 0.0
}`;

    TH_ANCHOR = playbookSpec.priority === 'CRITICAL' ? 0.86 : 0.85;

} else {
    // Fallback for unknown families
    paranoidSystem = `PARANOID ANALYSIS AGENT — ${family}
Family: ${family} | Status: NOT COVERED BY PLAYBOOK

YOUR MISSION
This clause family has no playbook specification. Analyze defensively.

ANALYZE FOR:
1. Party obligations and responsibilities
2. Timelines and conditions
3. Exclusions and limitations
4. Escape clauses or penalties
5. Any unusual or concerning language

OUTPUT FORMAT:
{
  "observations": [...],
  "summary": { "counts": {...}, "coverage_confidence": 0.0 },
  "risk_level": "YELLOW",
  "possible_family": "suggested family if identifiable"
}

IMPORTANT: Since no playbook exists, default to cautious analysis.`;

    valuatorSystem = `VALUATOR AGENT — ${family}
Status: NOT COVERED BY PLAYBOOK

RULES:
- final_status = NotCoveredByPlaybook
- escalation_recommended = true
- No proposed_changes (no playbook reference available)

OUTPUT: { "final_status": "NotCoveredByPlaybook", "escalation_recommended": true, "escalation_reason": "No playbook spec for ${family}", "proposed_changes": [], "confidence_overall": 0.0 }`;

    TH_ANCHOR = 0.85;
}

// -------------------------
// Build User Message (with RAG context)
// -------------------------
const ragBlock = `
RAG CONTEXT (for grounding only — DO NOT use as evidence; evidence must come from clause_text):
${formatRagExamples(ragContext)}`;

const paranoidUserMessage = `CLAUSE TEXT TO ANALYZE:
---
${clauseText}
---

${ragBlock}

INSTRUCTIONS:
1. First, check for ALL red flags (literal matches, case-insensitive)
2. Then, check for ALL must-have anchors (report missing ones)
3. Then, check for unacceptable patterns using examples for semantic matching
4. Finally, check for passable variations

Report EVERY finding with:
- evidence: exact substring from clause_text (or [missing: X])
- offsets: character positions in clause_text
- severity: high for red_flags/unacceptable, medium for passable, low for unknown

RESPOND ONLY WITH JSON.`;

// Build complete messages for OpenAI
const paranoidMessages = [
    { role: 'system', content: paranoidSystem },
    { role: 'user', content: paranoidUserMessage }
];

return [{
    json: {
        ...data,
        paranoidMessages,
        paranoidSystemPrompt: paranoidSystem,
        paranoidUserPrompt: paranoidUserMessage,
        valuatorSystemPrompt: valuatorSystem,
        TH_ANCHOR: TH_ANCHOR,
        usedDynamicPrompt: !!playbookSpec,
        promptVersion: '2.0',
        ragInjected: !!(ragContext && Object.keys(ragContext).length)
    }
}];

// =====================================================
// Parse Paranoid (CG-012-FIX) - Deterministic Red Flag Detection
// =====================================================
// COPIA ESTE CÓDIGO EN EL NODO "Parse Paranoid" DE n8n
// Este fix resuelve:
// 1. Severity override para observaciones del LLM con severidad incorrecta
// 2. Matching case-insensitive para red flags
// 3. Risk level determinístico: RED si hay red flags
// =====================================================

const prev = $('Build Family Prompt').first().json || {};
const clauseText = String(prev.clause_text || '');
const playbookSpec = prev.playbookSpec || {};
const matrix = playbookSpec.acceptability_matrix || {};
const detection = playbookSpec.detection_patterns || {};

const redFlags = Array.isArray(detection.red_flags) ? detection.red_flags : [];
const mustHave = Array.isArray(detection.must_have) ? detection.must_have : [];
const unacceptablePatterns = Array.isArray(matrix?.unacceptable?.patterns) ? matrix.unacceptable.patterns : [];

const raw = $json?.choices?.[0]?.message?.content || '{}';

// -------------------------
// Helpers
// -------------------------
function safeJsonParse(str) {
    try { return JSON.parse(str); } catch { return null; }
}

function escapeRegex(s) {
    return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function makeWsRegex(phrase) {
    const tokens = String(phrase).trim().split(/\s+/).filter(Boolean).map(escapeRegex);
    if (!tokens.length) return null;
    return new RegExp(tokens.join('\\s+'), 'gi');
}

function findAllOccurrences(text, phrase) {
    const rx = makeWsRegex(phrase);
    if (!rx) return [];
    const out = [];
    let m;
    while ((m = rx.exec(text)) !== null) {
        const start = m.index;
        const end = m.index + m[0].length;
        out.push({ evidence: text.slice(start, end), offsets: { start, end } });
        if (m[0].length === 0) rx.lastIndex++;
    }
    return out;
}

function bestEvidenceFromExample(text, example) {
    const words = String(example).match(/[A-Za-z0-9']+/g) || [];
    for (let n = Math.min(8, words.length); n >= 3; n--) {
        for (let i = 0; i + n <= words.length; i++) {
            const needle = words.slice(i, i + n).join(' ');
            const hits = findAllOccurrences(text, needle);
            if (hits.length) {
                return { ...hits[0], needle };
            }
        }
    }
    return null;
}

function toSeverity(riskLevel) {
    const v = String(riskLevel || '').toUpperCase();
    if (v === 'CRITICAL' || v === 'HIGH') return 'high';
    if (v === 'MEDIUM') return 'medium';
    return 'low';
}

function defaultOutput() {
    return {
        observations: [],
        summary: {
            counts: { total: 0, missing: 0, added: 0, modified: 0 },
            coverage_confidence: 0,
            red_flags_found: 0,
            unacceptable_patterns_found: 0,
            must_have_missing: 0
        },
        risk_level: 'GREEN'
    };
}

function normalizeParanoid(parsed) {
    const out = defaultOutput();
    if (parsed && typeof parsed === 'object') {
        if (Array.isArray(parsed.observations)) out.observations = parsed.observations;
        if (parsed.summary && typeof parsed.summary === 'object') out.summary = { ...out.summary, ...parsed.summary };
        if (typeof parsed.risk_level === 'string') out.risk_level = parsed.risk_level;
    }
    if (!Array.isArray(out.observations)) out.observations = [];
    if (!out.summary || typeof out.summary !== 'object') out.summary = defaultOutput().summary;
    if (!out.summary.counts || typeof out.summary.counts !== 'object') out.summary.counts = defaultOutput().summary.counts;
    if (typeof out.risk_level !== 'string') out.risk_level = 'GREEN';
    return out;
}

// =====================================================
// CG-012-FIX: Helper para matching case-insensitive de red flags
// =====================================================
function matchesRedFlag(text, redFlags) {
    const textLower = String(text || '').toLowerCase();
    for (const rf of redFlags) {
        const rfLower = String(rf).toLowerCase();
        if (textLower.includes(rfLower) || rfLower.includes(textLower.substring(0, 20))) {
            return rf;
        }
    }
    return null;
}

// -------------------------
// 1) Parse LLM JSON
// -------------------------
const parsed = safeJsonParse(raw);
let paranoidOutput = normalizeParanoid(parsed);

// =====================================================
// CG-012-FIX: SEVERITY OVERRIDE FOR LLM OBSERVATIONS
// =====================================================
// If LLM returned observations but assigned wrong severity to red flags,
// FORCE severity=high and possible_category=MatchesUnacceptable
let severityOverrideCount = 0;
for (const obs of paranoidOutput.observations) {
    const evidenceLower = String(obs.evidence || '').toLowerCase();

    const matchedFlag = matchesRedFlag(obs.evidence, redFlags);

    if (matchedFlag) {
        if (obs.severity !== 'high') {
            obs.severity = 'high';
            severityOverrideCount++;
        }
        if (obs.possible_category !== 'MatchesUnacceptable') {
            obs.possible_category = 'MatchesUnacceptable';
        }
        obs.pattern_matched = matchedFlag;
        obs.confidence = Math.max(obs.confidence || 0.7, 0.95);
        obs.reason = obs.reason ? obs.reason + ` [GUARDRAIL: Red flag '${matchedFlag}' detected]` : `GUARDRAIL: Red flag '${matchedFlag}' detected`;
    }
}

// -------------------------
// 2) Deterministic findings (guardrail)
// -------------------------
const injected = [];

// 2.1 Red flags
for (const flag of redFlags) {
    const hits = findAllOccurrences(clauseText, flag);
    for (const h of hits) {
        injected.push({
            evidence: h.evidence,
            offsets: h.offsets,
            change_type: 'modified',
            possible_category: 'MatchesUnacceptable',
            pattern_matched: String(flag),
            confidence: 0.95,
            severity: 'high',
            reason: `Red flag found: "${flag}"`,
            playbook_reference: null
        });
    }
}

// 2.2 Must-have
for (const anchor of mustHave) {
    const hits = findAllOccurrences(clauseText, anchor);
    if (!hits.length) {
        injected.push({
            evidence: `[missing: ${anchor}]`,
            offsets: { start: 0, end: 0 },
            change_type: 'missing',
            possible_category: 'MissingRequired',
            pattern_matched: String(anchor),
            confidence: 0.95,
            severity: 'high',
            reason: `Missing required must-have element: "${anchor}"`,
            playbook_reference: null
        });
    }
}

// 2.3 Unacceptable patterns
for (const p of unacceptablePatterns) {
    const pat = (p && typeof p === 'object') ? p : { pattern: String(p) };
    const patternName = String(pat.pattern || '').trim();
    const example = String(pat.example || '').trim();
    const isShort = patternName.length > 0 && patternName.length <= 40;

    let hits = [];
    let matchedBy = null;

    if (isShort && patternName) {
        hits = findAllOccurrences(clauseText, patternName);
        if (hits.length) matchedBy = patternName;
    }

    if (!hits.length && example) {
        hits = findAllOccurrences(clauseText, example);
        if (hits.length) matchedBy = example;
    }

    if (!hits.length && example) {
        const best = bestEvidenceFromExample(clauseText, example);
        if (best) {
            hits = [{ evidence: best.evidence, offsets: best.offsets }];
            matchedBy = best.needle || example;
        }
    }

    for (const h of hits) {
        injected.push({
            evidence: h.evidence,
            offsets: h.offsets,
            change_type: 'modified',
            possible_category: 'MatchesUnacceptable',
            pattern_matched: patternName || matchedBy || 'UnacceptablePattern',
            confidence: 0.90,
            severity: toSeverity(pat.risk_level),
            reason: pat.reason || `Matches unacceptable pattern: ${patternName || matchedBy}`,
            playbook_reference: pat.id || null
        });
    }
}

// -------------------------
// 3) Merge strategy
// -------------------------
function obsKey(o) {
    const start = o?.offsets?.start ?? -1;
    const end = o?.offsets?.end ?? -1;
    const pat = String(o?.pattern_matched ?? '');
    const ev = String(o?.evidence ?? '');
    return `${start}:${end}:${pat}:${ev}`;
}

if (paranoidOutput.observations.length === 0 && injected.length > 0) {
    paranoidOutput.observations = injected;
} else if (injected.length > 0) {
    const existing = new Set(paranoidOutput.observations.map(obsKey));
    for (const inj of injected) {
        const k = obsKey(inj);
        if (!existing.has(k)) paranoidOutput.observations.push(inj);
    }
}

// -------------------------
// 4) Recompute summary + risk_level deterministically
// -------------------------
const obs = paranoidOutput.observations;

const counts = {
    total: obs.length,
    missing: obs.filter(o => o.change_type === 'missing').length,
    added: obs.filter(o => o.change_type === 'added').length,
    modified: obs.filter(o => o.change_type === 'modified').length
};

// =====================================================
// CG-012-FIX: Count red flags using case-insensitive partial matching
// =====================================================
const redFlagsFound = obs.filter(o => {
    const patLower = String(o.pattern_matched || '').toLowerCase();
    return redFlags.some(rf => patLower.includes(rf.toLowerCase()) || rf.toLowerCase().includes(patLower));
}).length;

const mustHaveMissing = obs.filter(o => o.possible_category === 'MissingRequired').length;
const unacceptableFound = obs.filter(o => o.possible_category === 'MatchesUnacceptable').length;

// =====================================================
// CG-012-FIX: DETERMINISTIC RISK LEVEL
// =====================================================
let risk = 'GREEN';
if (redFlagsFound > 0 || unacceptableFound > 0 || mustHaveMissing > 0) {
    risk = 'RED';
} else if (obs.some(o => o.severity === 'high')) {
    risk = 'RED';
} else if (obs.some(o => o.severity === 'medium')) {
    risk = 'YELLOW';
}

paranoidOutput.summary = {
    ...paranoidOutput.summary,
    counts,
    red_flags_found: redFlagsFound,
    unacceptable_patterns_found: unacceptableFound,
    must_have_missing: mustHaveMissing,
    coverage_confidence: paranoidOutput.summary?.coverage_confidence ?? 0
};
paranoidOutput.risk_level = risk;

const guardrailTriggered = injected.length > 0 || severityOverrideCount > 0;

// -------------------------
// 5) Return merged data
// -------------------------
return [{
    json: {
        ...prev,
        paranoidOutput,
        paranoidRaw: raw,
        paranoid_guardrail_triggered: guardrailTriggered,
        paranoid_guardrail_injected_count: injected.length,
        paranoid_severity_overrides: severityOverrideCount
    }
}];

